// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set MinSum to 10 (only works before initialized)
        c.SetMinSum(10);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Deployer sends 5 ether with locktime 1 second
        vm.deal(address(this), 5 ether);
        c.Put{value: 5 ether}(1);

        // Warp past unlock time
        vm.warp(block.timestamp + 2);

        // Attempt to collect 5 ether
        uint balanceBefore = address(c).balance;
        try c.Collect(5 ether) {
            // If Collect succeeds, contract balance decreases by 5 ether
        } catch {
            // If Collect reverts, contract balance unchanged
        }
        uint balanceAfter = address(c).balance;

        // Reference: 5 < 10, so Collect reverts => balance unchanged
        // Mutant: MinSum=0, so 5 >= 0, Collect succeeds => balance drops by 5 ether
        // Assert that balance changed (mutant) vs unchanged (reference)
        assertTrue(balanceBefore != balanceAfter, "Balance must differ between reference and mutant");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set MinSum to 100 (reference allows this before initialization)
        c.SetMinSum(100);
        // Initialize the contract
        c.Initialized();
        // Fund user address 0x1 with 200 wei, deposit 50 wei with no lock (lockTime = 0)
        address user = address(0x1);
        vm.deal(user, 200);
        vm.prank(user);
        c.Put{value: 50}(0);
        // Warp past the unlockTime (which is block.timestamp + 0 = original block.timestamp)
        vm.warp(block.timestamp + 1);
        // Now user tries to Collect(50); since balance=50 < MinSum=100, reference reverts, mutant doesn't
        bool ok;
        vm.prank(user);
        try c.Collect(50) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference (C) should revert because MinSum=100 > 50, so ok is false
        // Mutant (MinSum=0) allows, so ok is true
        assertTrue(!ok, "Reference should revert, mutant should not");
    }
}

