pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: set MinSum to 100, initialize
        c.SetMinSum(100);
        c.Initialized();

        // User deposits 50 wei and lock time passes
        address user = address(0x1234);
        vm.deal(user, 50);
        vm.prank(user);
        c.Put{value: 50}(1);  // lock time = 1 second

        vm.warp(block.timestamp + 2); // lock time passed

        // Try Collect(50) - should revert in reference, succeed in mutant
        bool success;
        vm.prank(user);
        try c.Collect(50) {
            success = true;
        } catch {
            success = false;
        }

        // Assert: in reference (MinSum is 100) Collect reverts (success=false)
        // But in mutant (MinSum forced to 0) Collect succeeds (success=true)
        // We assert that Collect reverts (true for reference, false for mutant)
        assertTrue(!success, "Collect should revert in reference");
    }
}

