import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Step 1: Set MinSum to 10 (only works before Initialized)
        c.SetMinSum(10);
        c.Initialized();

        // Step 2: User deposits 5 wei with lock time 0 (so unlock time = block.timestamp)
        address user = address(0x1234);
        vm.deal(user, 5);
        vm.prank(user);
        c.Put{value: 5}(0);

        // Step 3: warp to after unlock time (already passed since lock time = 0)
        vm.warp(block.timestamp + 1);

        // Step 4: Call Collect(5); reference reverts (MinSum=10 > 5), mutant succeeds
        vm.prank(user);
        bool ok;
        try c.Collect(5) { ok = true; } catch { ok = false; }

