pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set MinSum to 100 (reference will keep it 100; mutant will set it to 0 regardless)
        c.SetMinSum(100);
        c.SetLogFile(address(0x1234)); // dummy, won't be called
        c.Initialized();

        // Alice deposits 200 wei with lock time 0 (opens immediately)
        address alice = address(0xAAAA);
        vm.deal(alice, 200);
        vm.prank(alice);
        c.Put{value: 200}(0);

        // Warp past lock time (already 0, but ensure)
        vm.warp(block.timestamp + 1);

        // Alice attempts Collect(200)
        vm.prank(alice);
        bool ok;
        try c.Collect(200) { ok = true; } catch { ok = false; }

        // Reference: MinSum=100, balance=200 >= 100, so revert because balance >= MinSum is true, but actually condition is:
        // if( acc.balance>=MinSum && acc.balance>=_am && block.timestamp>acc.unlockTime )
        // MinSum=100, balance=200 >= 100, _am=200, balance(200)>=200 true, time >0 true => Collect succeeds.
        // Wait, that's not the expected difference. Let me reconsider: the mutant sets MinSum to 0 always, but reference sets MinSum=100.
        // For Collect to differ, need acc.balance >= MinSum. If balance < MinSum in reference, it fails, but in mutant MinSum=0 so it passes.
        // So pick Alice deposits 50 wei (<100), then Collect(50): reference fails (balance 50 < 100), mutant passes.
        // Let's do that:
        address bob = address(0xBBBB);
        vm.deal(bob, 50);
        vm.prank(bob);
        c.Put{value: 50}(0);

        vm.warp(block.timestamp + 1);

        vm.prank(bob);
        bool ok2;
        try c.Collect(50) { ok2 = true; } catch { ok2 = false; }

        // Reference: balance=50 < MinSum=100 => revert => ok2 false
        // Mutant: MinSum=0 => condition passes => ok2 true
        // Assert that ok2 is true (which is only true for mutant, fail for reference)
        // Actually we want the test to PASS on reference (reference behavior = fail) and FAIL on mutant (mutant behavior = success).
        // So assert that Collect succeeds (ok2 true) will fail on reference (which reverts) and pass on mutant.
        assertTrue(ok2, "Collect should have succeeded (only in mutant)");
    }
}

