contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set MinSum to 1 so that Collect can succeed
        c.SetMinSum(1);
        // Initialize the contract
        c.Initialized();
        // Use a specific user address
        address user = address(0x123);
        // Give user some ether
        vm.deal(user, 1 ether);
        // User puts 1 wei with lockTime = 0
        vm.prank(user);
        c.Put{value: 1 wei}(0);
        // Warp to some time after block.timestamp so unlockTime (if set) becomes <= block.timestamp
        vm.warp(block.timestamp + 1);
        // User collects 1 wei
        vm.prank(user);
        c.Collect(1 wei);
        // Now read the unlockTime for the user via the public mapping getter
        (uint unlockTime, ) = c.Acc(user);
        // In the reference contract, unlockTime was set to block.timestamp + 0 = initial block.timestamp + 1 (since we warped after the Put)
        // Actually in Put: acc.unlockTime = block.timestamp + _lockTime; call was at time T0, then we warped to T1, so unlockTime = T0
        // So after Collect, unlockTime is still T0 (unchanged by Collect). The buggy contract never set unlockTime, so it's 0.
        // Since T0 > 0, the reference unlockTime is > 0, bug is 0. Assert that unlockTime is not zero (reference holds).
        assertTrue(unlockTime != 0, "UnlockTime should be non-zero in reference");
    }
}

