pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initial setup
        c.SetMinSum(1 ether);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // First caller: puts 1 ether with lock time 100 seconds
        address alice = address(0x1111);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.Put{value: 1 ether}(100);

        // Second caller: puts 1 ether with lock time 0 seconds
        address bob = address(0x2222);
        vm.deal(bob, 1 ether);
        vm.prank(bob);
        c.Put{value: 1 ether}(0);

        // Warp to after alice's lock time (but bob's first put had unlockTime = block.timestamp + 0)
        vm.warp(block.timestamp + 101);

        // Bob does a second Put(0) – in reference, this would NOT update unlockTime (since block.timestamp+0 > old unlockTime? Actually old unlockTime = block.timestamp_old+0; if we warp, new timestamp+0 > old? Let's trace:
        // Initially block.timestamp = 0. After first Put: alice unlockTime = 100, bob unlockTime = 0.
        // After warp to 101: bob's old unlockTime = 0, so block.timestamp+0 = 101 > 0 -> condition true, update to 101 (reference) / false (mutant) -> stays 0.
        // So we put bob's second Put here to trigger the mutant's bug
        vm.prank(bob);
        c.Put{value: 0}(0);

        // Now bob's unlockTime:
        // Reference: 101, Mutant: 0

        // Bob tries to Collect 1 ether: needs balance >= MinSum (1 ether), balance >= _am, and timestamp > unlockTime
        // For reference: timestamp = 101, unlockTime = 101 -> timestamp NOT > unlockTime, so revert.
        // For mutant: unlockTime = 0, timestamp = 101 > 0, so collect succeeds.
        // To get reference success vs mutant failure, we need opposite.
        // Let's try: alice tries to collect small amount?
        // Actually let's set up so that reference succeeds and mutant fails:
        // After above, bob's unlockTime: reference 101, mutant 0.
        // Collect with _am = 0.5 ether at timestamp 101:
        // Reference: 101 > 101? No -> revert
        // Mutant: 101 > 0? Yes -> succeeds
        // So we want a scenario where reference succeeds and mutant fails.
        // For reference to succeed, we need timestamp > unlockTime in reference but <= unlockTime in mutant.
        // That would require mutant's unlockTime >= timestamp and reference's unlockTime < timestamp.
        // Since reference sets unlockTime to later (max), mutant to earlier (min), this can't happen if both start from same.
        // But if we use different callers: alice puts with long lockTime, bob puts with short, then alice's unlockTime is set by reference to long, by mutant to short.
        // At timestamp between long and short: reference fails, mutant succeeds.
        // At timestamp after long: both succeed.
        // To get reference success and mutant failure: need timestamp such that reference unlockTime < timestamp (success) but mutant unlockTime >= timestamp (failure). This would require mutant unlockTime > reference unlockTime, but our mutant sets unlockTime to MIN of old and new, so it can only be <= reference. So impossible.
        // Therefore the only observable difference is: reference may succeed while mutant fails (or vice versa) depending on threshold.
        // Let's instead try to make a collect succeed in reference but fail in mutant:
        // Have bob do Put(0) at time 0 -> unlockTime = 0 (both). Then warp to, say, 10. Reference: Put(100) -> unlockTime = max(0, 10+100=110) = 110. Mutant: min(0,110)=0. At timestamp 50: reference unlockTime=110 > 50 => fail; mutant unlockTime=0 <50 => succeed. So mutant succeeds, reference fails.
        // To get reference succeed, mutant fail: need mutant unlockTime > timestamp and reference unlockTime < timestamp, which would require mutant to have HIGHER unlockTime, impossible.
        // Thus the only difference direction is reference fail, mutant succeed. So our test should assert that in reference, collect FAILS; in mutant, it SUCCEEDS.
        // But the problem statement says the assertion the original satisfies and mutant breaks: original P.Put() != M.Put(). So we need to check something that differs.
        // Let's check that after Collect, the balance differs.
        // We'll set up so reference's Collect fails (revert) and mutant's Collect succeeds (balance changes).
        // That means the assertTrue should be that a collect succeeds? But reference doesn't have that. Probably we check balance unchanged in reference, changed in mutant.
        // Let's redo cleanly:
        // Deploy new C in setUp(). Call:
        // 1. SetMinSum(1 ether)
        // 2. SetLogFile
        // 3. Initialized
        // 4. Alice: Put(100) with 1 ether at time 0 -> unlockTime=100 (ref), unlockTime=100 (mutant)
        // 5. Bob: Put(0) with 1 ether at time 0 -> unlockTime=0 (both)
        // 6. Warp to time 50
        // 7. Bob: Put(0) with 0 ether -> reference: unlockTime = max(0, 50) = 50; mutant: min(0,50) = 0
        // 8. Warp to time 60
        // 9. Alice tries Collect(0.5 ether): requires timestamp > unlockTime. For reference: unlockTime=100, 60>100 false => revert. For mutant: unlockTime=100, false => revert. Both same. Need different.
        // Bob: for reference unlockTime=50, 60>50 true => success. For mutant unlockTime=0, true => success. Both same.
        // We need a case where reference succeeds and mutant fails: impossible as argued.
        // So we accept the opposite: we set up so reference fails (revert) and mutant succeeds. Then we check that after the call, bob's balance stayed the same in reference but decreased in mutant.
        // Actually simpler: let's just check the unlockTime of a specific holder after a sequence of Puts.
        // For the same inputs, the unlockTime will differ after certain Puts.
        // Let's do:
        // 1. Alice: Put(100) with 0 ether at time 0 -> unlockTime = 100 (both)
        // 2. Warp to 200
        // 3. Alice: Put(50) with 0 ether -> reference: unlockTime = max(100, 200+50=250) = 250; mutant: min(100,250) = 100
        // Now assert that in reference, unlockTime == 250; in mutant, unlockTime == 100 (so in mutant it's 100, not 250).
        // So we can assert: c.Acc(alice).unlockTime == 250 (reference true, mutant false). That's a getter.
        // That's a clean concrete scenario. Let's code that.

        // Reset with fresh contract
        c = new C();
        c.SetMinSum(1 ether);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        address alice = address(0x1111);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.Put{value: 0}(100);

        vm.warp(200);

        vm.prank(alice);
        c.Put{value: 0}(50);

        // Now check unlockTime
        (uint unlockTime, ) = c.Acc(alice);
        assertTrue(unlockTime == 250); // In reference, unlockTime = 250. In mutant, unlockTime = 100. So this assert passes on reference, fails on mutant.
    }
}

