        vm.warp(unlockTime);

        // Set MinSum to 0 (so balance >= MinSum is true)
        c.SetMinSum(0);
        c.Initialized();

        // Now call Collect - in reference it reverts, in buggy it succeeds
        bool ok;
        vm.prank(alice);
        try c.Collect(0.5 ether) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: Collect reverts because block.timestamp > acc.unlockTime is false
        // Buggy: Collect succeeds because block.timestamp >= acc.unlockTime is true
        // So ok is false for reference, true for buggy; we assert ok is false (reference behavior)
        assertTrue(!ok, "In reference, Collect should revert when block.timestamp == acc.unlockTime");
    }
}
